            </label>
        </div>
    </div>
    <div class="txt-center float-btn-dark">
        <?php if ($signup_link != '') : ?>
        <a href="<?php echo $signup_link ?>" class="btn-dark-green-2 hover disabled js-button"><span>THAM GIA NGAY</span></a>
        <?php elseif ($step == 'lock'): ?>
        <a class="btn-dark-green-2 hover js-btn-lock disabled js-button"><span>THAM GIA NGAY</span></a>
        <?php else: ?>
        <a class="btn-dark-green-2 hover js-btn-terms-submit disabled js-button" data-modal="<?php echo $next_step ?>" data-step="<?php echo $step ?>"><span>THAM GIA NGAY</span></a>
        <?php endif ?>
    </div>
</div>
